## Why This Is Asked

This question tests practical Azure fundamentals including HTTP triggers, blob storage streaming, per-tenant isolation, and Cosmos DB partitioning. It also validates understanding of security (Managed Identity), idempotency (deduplication by fileName), and cost-conscious deployment workflows.

## Key Concepts

- HTTP-triggered Azure Functions
- Multipart/form-data parsing and streaming
- Azure Blob Storage with per-tenant paths
- Cosmos DB with tenantId partition key
- Managed Identity for secure resource access
- Idempotent ingestion via fileName deduplication
- GitHub Actions with App Configuration and Key Vault

## Code Example

```javascript
// index.js
const { ContainerClient } = require('@azure/storage-blob');
const { CosmosClient } = require('@azure/cosmos');

module.exports = async function (context, req) {
    const tenantId = req.query.tenantId;
    const fileName = req.body?.filename || req.headers['x-filename'];

    if (!tenantId || !fileName) {
        context.res = { status: 400, body: 'Missing tenantId or fileName' };
        return;
    }

    const blobServiceClient = new ContainerClient(
        `https://${process.env.STORAGE_ACCOUNT}.blob.core.windows.net/${tenantId}`,
        new DefaultAzureCredential()
    );

    const blockBlobClient = blobServiceClient.getBlockBlobClient(fileName);
    const uploadStream = async (readableStream) => {
        let rowCount = 0;
        return new Promise((resolve, reject) => {
            readableStream.on('data', (data) => {
                rowCount += data.toString().split('\n').length - 1;
            });
            readableStream.on('end', () => resolve(rowCount));
            readableStream.on('error', reject);
        });
    };

    const stream = req.body;
    const rowCount = await uploadStream(stream);
    await blockBlobClient.uploadStream(stream);

    const cosmosClient = new CosmosClient({
        endpoint: process.env.COSMOS_ENDPOINT,
        credential: new DefaultAzureCredential()
    });

    const container = cosmosClient.database('ingestion').container('files');
    await container.items.upsert({
        id: `${tenantId}-${fileName}`,
        tenantId,
        fileName,
        uploadTime: new Date().toISOString(),
        rowCount
    });

    context.res = { status: 200, body: { rowCount } };
};
```

## GitHub Actions Pipeline

```yaml
name: Deploy CSV Ingestion API

on: [push]

jobs:
  deploy:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Azure Login
        uses: azure/login@v1
        with:
          creds: ${{ secrets.AZURE_CREDENTIALS }}

      - name: Fetch App Config
        run: |
          az appconfig kv export \
            --name ${{ vars.APP_CONFIG_NAME }} \
            --connection-string ${{ secrets.APP_CONFIG_CONN }} \
            --prefix CSV_INGESTION_ \
            --format json > appconfig.json

      - name: Fetch Key Vault Secrets
        run: |
          for secret in STORAGE_ACCOUNT COSMOS_ENDPOINT; do
            echo "$secret=${{ secrets.$secret }}" >> $GITHUB_ENV
          done

      - name: Azure Functions Deploy
        uses: Azure/functions-action@v1
        with:
          app-name: csv-ingestion-api
          package: ${{ github.workspace }}/function.zip
```

